-- iPM_REPL.dbo.REFERENCE_VALUES: production-shaped schema for conduit's
-- integration specs, derived from the tracked dump in
-- spec/support/mssql_production_schemas/iPM_REPL/REFERENCE_VALUES.sql.
-- Columns are verbatim; production indexes are omitted (they do
-- not affect correctness). Rows reset to an anonymised production
-- sample on each seeding; the seeder refuses to run against a
-- real-looking instance. Idempotent; runs after database.sql.

USE [iPM_REPL];
GO

IF OBJECT_ID('dbo.REFERENCE_VALUES') IS NULL
BEGIN
  CREATE TABLE dbo.REFERENCE_VALUES (
	RFVAL_REFNO numeric(10,0) NOT NULL,
	RFVDM_CODE varchar(5) COLLATE Latin1_General_CI_AS NOT NULL,
	DESCRIPTION varchar(80) COLLATE Latin1_General_CI_AS NULL,
	MAIN_CODE varchar(25) COLLATE Latin1_General_CI_AS NULL,
	PARNT_REFNO numeric(10,0) NULL,
	SMODE_VALUE varchar(5) COLLATE Latin1_General_CI_AS NOT NULL,
	DEFAULT_VALUE char(1) COLLATE Latin1_General_CI_AS NOT NULL,
	SORT_ORDER numeric(3,0) NOT NULL,
	SELECT_VALUE char(1) COLLATE Latin1_General_CI_AS NOT NULL,
	DISPLAY_VALUE char(1) COLLATE Latin1_General_CI_AS NOT NULL,
	OWNER_HEORG_REFNO numeric(10,0) NULL,
	CREATE_DTTM datetime2 NOT NULL,
	MODIF_DTTM datetime2 NOT NULL,
	USER_CREATE varchar(30) COLLATE Latin1_General_CI_AS NOT NULL,
	USER_MODIF varchar(30) COLLATE Latin1_General_CI_AS NOT NULL,
	RFTYP_CODE varchar(5) COLLATE Latin1_General_CI_AS NOT NULL,
	ARCHV_FLAG char(1) COLLATE Latin1_General_CI_AS NULL,
	STRAN_REFNO numeric(10,0) NULL,
	PRIOR_POINTER numeric(10,0) NULL,
	EXTERNAL_KEY varchar(20) COLLATE Latin1_General_CI_AS NULL,
	START_DTTM datetime2 NULL,
	END_DTTM datetime2 NULL,
	LOW_VALUE varchar(30) COLLATE Latin1_General_CI_AS NULL,
	HIGH_VALUE varchar(30) COLLATE Latin1_General_CI_AS NULL,
	PROCESS_MODULE_ID varchar(20) COLLATE Latin1_General_CI_AS NULL,
	SCLVL_REFNO numeric(10,0) NULL,
	SYN_CODE varchar(20) COLLATE Latin1_General_CI_AS NULL
  );
END
GO

-- Reset to the canonical sample. Plain DELETE is safe here: the
-- seeder aborts before running any script when the instance
-- looks real (see spec/support/mssql_seed_integration_tests.rb).
DELETE FROM dbo.REFERENCE_VALUES;
GO

-- Domain rows for the descriptions the patient queries resolve:
-- ETHGR (ATSI status) refnos carried by the PATIENTS sample, and
-- GENDR refnos likewise. Same reset guarantee as the rows above.
GO
